package main
import("encoding/json";"fmt";"os";"path/filepath";"github.com/alekpopovic/orch/internal/cli";"github.com/alekpopovic/orch/pkg/types";"gopkg.in/yaml.v3")
func main(){root:=os.Args[1]; results:=map[string]any{};for _,name:=range []string{"atlas-api.yaml","atlas-api-constrained.yaml","atlas-api-unhealthy.yaml","atlas-invalid-unknown-field.yaml"}{spec,err:=cli.ParseDeployFile(filepath.Join(root,name));shouldFail:=name=="atlas-invalid-unknown-field.yaml";if shouldFail!=(err!=nil){panic(fmt.Sprintf("unexpected parser outcome %s: %v",name,err))};r:=map[string]any{"accepted":err==nil,"expected_rejection":shouldFail};if err!=nil{r["error"]=err.Error()}else{r["name"]=spec.Name;r["replicas"]=spec.Replicas};results[name]=r};data,err:=os.ReadFile(filepath.Join(root,"atlas-count.yaml"));if err!=nil{panic(err)};var m struct{Name,Image string;Command []string;BackoffLimit int `yaml:"backoffLimit"`;Resources struct{CPU,Memory string}};if err=yaml.Unmarshal(data,&m);err!=nil{panic(err)};cpu,err:=types.ParseCPU(m.Resources.CPU);if err!=nil{panic(err)};mem,err:=types.ParseMemory(m.Resources.Memory);if err!=nil{panic(err)};s:=types.JobSpec{Name:m.Name,Image:m.Image,Command:m.Command,BackoffLimit:m.BackoffLimit,ResourceRequirements:types.ResourceRequirements{Requests:types.Resources{CPU:cpu,Memory:mem},Limits:types.Resources{CPU:cpu,Memory:mem}}};if err=s.Validate();err!=nil{panic(err)};results["atlas-count.yaml"]=map[string]any{"accepted":true,"parser":"job CLI-equivalent envelope plus actual JobSpec.Validate","command":s.Command,"container_execution":"not_run"};json.NewEncoder(os.Stdout).Encode(results)}
